function Get-LogSnapshot {
    param([string]$Path)

    $snap = [ordered]@{
        path = $Path
        exists = $false
        size = 0
        lastWrite = $null
        lineCount = 0
        conexoes = @()
        desconexoes = @()
        outras = @()
        rawTail = @()
    }

    if (-not (Test-Path -LiteralPath $Path)) { return $snap }

    $item = Get-Item -LiteralPath $Path
    $bytes = [System.IO.File]::ReadAllBytes($Path)
    $text = [System.Text.Encoding]::UTF8.GetString($bytes)
    if ($text.StartsWith([char]0xFEFF)) { $text = $text.Substring(1) }
    $text = $text -replace "`r`n", "`n" -replace "`r", "`n"
    $lines = @($text -split "`n" | Where-Object { $_.Trim() -ne "" })

    $snap.exists = $true
    $snap.size = $item.Length
    $snap.lastWrite = $item.LastWriteTime.ToString("o")
    $snap.lineCount = $lines.Count

    foreach ($line in $lines) {
        $plain = $line
        $idx = $line.LastIndexOf($HashMarker)
        if ($idx -ge 0) { $plain = $line.Substring(0, $idx) }

        if ($plain -match "acesso remoto via Veyon") {
            $snap.conexoes += $plain
        } elseif ($plain -match "encerramento da conex") {
            $snap.desconexoes += $plain
        } else {
            $snap.outras += $plain
        }
    }

    $snap.rawTail = @($lines | Select-Object -Last 5)
    return $snap
}

function Get-VeyonRuntimeSnapshot {
    $procs = Get-CimInstance Win32_Process -ErrorAction SilentlyContinue |
        Where-Object { $_.Name -in @("veyon-server.exe", "veyon-worker.exe", "veyon-master.exe") } |
        Select-Object ProcessId, Name, ExecutablePath, @{ n = "StartTime"; e = { $_.CreationDate } }

    $serverLog = $VeyonServerLogs | Where-Object { Test-Path $_ } | Select-Object -First 1
    $logTail = @()
    $logMarkers = @()

    if ($serverLog) {
        $logTail = Get-Content $serverLog -Tail 80 -Encoding UTF8 -ErrorAction SilentlyContinue
        $patterns = @(
            "showAccessControlMessage",
            "handleProxyConnectionClosed",
            "gravarLog",
