function Write-Event([string]$Msg, [string]$Color = "White") {
    $line = "[$(Get-Date -Format 'HH:mm:ss')] $Msg"
    Add-Content -Path $EventLog -Value $line -Encoding UTF8
    Write-Host $line -ForegroundColor $Color
}

$positions = @{
    master = if (Test-Path $LocalMasterLog) { (Get-Item $LocalMasterLog).Length } else { 0 }
    server = if (Test-Path $RemoteServerLog) { (Get-Item $RemoteServerLog).Length } else { 0 }
}
$seen = @{}
$end = (Get-Date).AddSeconds($Seconds)

Write-Host "`n=== MONITOR TRANSFERENCIA (.86 -> .119) ===" -ForegroundColor Cyan
