    foreach ($pair in @(
        @{ name = "MASTER"; path = $LocalMasterLog; key = "master" },
        @{ name = "SERVER.$RemoteHost"; path = $RemoteServerLog; key = "server" }
    )) {
        if (-not (Test-Path $pair.path)) { continue }
        $item = Get-Item $pair.path
        if ($item.Length -lt $positions[$pair.key]) { $positions[$pair.key] = 0 }
        if ($item.Length -le $positions[$pair.key]) { continue }

        $stream = [IO.File]::Open($pair.path, 'Open', 'Read', 'ReadWrite')
        $stream.Seek($positions[$pair.key], 'Begin') | Out-Null
        $reader = New-Object IO.StreamReader($stream)
        while (($line = $reader.ReadLine()) -ne $null) {
            $hit = $false
            foreach ($m in $markers) {
                if ($line -match [regex]::Escape($m) -or $line -match $m) { $hit = $true; break }
            }
            if ($hit) {
                $hash = "$($pair.name):$line"
                if (-not $seen.ContainsKey($hash)) {
                    $color = if ($line -match "disabled by configuration") { "Red" }
                             elseif ($line -match "FileTransferResult|Received file") { "Green" }
                             elseif ($line -match "error|failed|Timed out") { "Red" }
                             else { "Cyan" }
                    Write-Event "[$($pair.name)] $line" $color
                    $seen[$hash] = $true
                }
            }
        }
        $positions[$pair.key] = $stream.Position
        $reader.Close(); $stream.Close()
    }
    Start-Sleep -Milliseconds 500
}

