}

function Start-ScreenWatch {
    New-Item -ItemType Directory -Path $SessionDir -Force | Out-Null
    if (Test-Path $EventLog) { Remove-Item $EventLog -Force }
    $lastSize = if (Test-Path $LogFile) { (Get-Item $LogFile).Length } else { 0 }
    $seen = @{}
