    Write-Host "`nConecte AGORA da .119 e abra controle remoto`n" -ForegroundColor Yellow

    while ((Get-Date) -lt $end) {
        $from119 = Get-NetTCPConnection -ErrorAction SilentlyContinue |
            Where-Object { $_.RemoteAddress -eq $RemoteIp -and $_.LocalPort -eq 11100 -and $_.State -eq 'Established' }
