            Write-Event "TCP .119 -> :11100 ESTABLISHED"
            $seen['tcp'] = $true
        }

        if (Test-Path $LogFile) {
            $size = (Get-Item $LogFile).Length
            if ($size -gt $lastSize) {
                $lines = Get-Content $LogFile -Encoding UTF8 -ErrorAction SilentlyContinue | Select-Object -Last 40
                foreach ($line in $lines) {
                    $hit = ($ScreenMarkers | Where-Object { $line -match $_ }).Count -gt 0
                    if ($hit -and -not $seen.ContainsKey($line)) {
                        Write-Event "LOG: $($line.Substring(0, [Math]::Min(220, $line.Length)))"
                        $seen[$line] = $true

                        if ($line -match 'QueryScreens.*Screen 1.*Screen 2') {
                            if ($line -match 'geometry":null') {
                                Write-Event "PROBLEMA: geometry null no QueryScreens -> menu All screens/Screen 1/2 nao funciona no Master"
                            } else {
                                Write-Event "OK: QueryScreens com geometry preenchida"
                            }
                        }
                        if ($line -match 'bitmap dimensions are (\d+) x (\d+)') {
                            Write-Event "UltraVNC framebuffer: $($Matches[1])x$($Matches[2])"
                        }
                    }
                }
                $lastSize = $size
            }
        }
        Start-Sleep -Milliseconds 400
    }
    Write-Host "`nMonitor encerrado. Eventos: $EventLog" -ForegroundColor Yellow
}

