function Get-Ipv4Addresses {
    try {
        return @(Get-NetIPAddress -AddressFamily IPv4 -ErrorAction Stop |
            Where-Object { $_.IPAddress -notlike "127.*" } |
            Select-Object -ExpandProperty IPAddress)
    } catch {
        $ip = (ipconfig | Select-String "IPv4" | Select-Object -First 1).ToString()
        if ($ip -match ":\s*([0-9.]+)") { return @($Matches[1]) }
        return @()
    }
}

function Get-FileSnapshot {
    param([string]$Path, [string]$Label, [switch]$SkipRead)

    $snap = [ordered]@{
        label = $Label
        path = $Path
        exists = $false
        size = 0
        lastWrite = $null
        lineCount = 0
        alerts = @()
        rawTail = @()
        accessNote = $null
    }

    if ($Path -match '^\\\\') {
        $snap.accessNote = "rede verificada apenas no watch (evita travar baseline)"
        return $snap
    }

    if (-not (Test-Path -LiteralPath $Path -ErrorAction SilentlyContinue)) { return $snap }

    $item = Get-Item -LiteralPath $Path -ErrorAction SilentlyContinue
    if (-not $item) { return $snap }

    $snap.exists = $true
    $snap.size = $item.Length
    $snap.lastWrite = $item.LastWriteTime.ToString("o")

    if (-not $SkipRead) {
        $lines = @(Get-Content -LiteralPath $Path -Encoding UTF8 -ErrorAction SilentlyContinue | Where-Object { $_.Trim() -ne "" })
        $snap.lineCount = $lines.Count
        $snap.alerts = @($lines)
        $snap.rawTail = @($lines | Select-Object -Last 5)
    }

    return $snap
}

function Get-VeyonProcesses {
    $out = @()
    foreach ($name in @("veyon-server.exe", "veyon-worker.exe", "veyon-master.exe")) {
        $p = Get-Process -Name ($name -replace '\.exe$','') -ErrorAction SilentlyContinue
        foreach ($proc in $p) {
            $path = $null
            try { $path = $proc.Path } catch {}
            $out += [ordered]@{
                ProcessId = $proc.Id
                Name = $name
                ExecutablePath = $path
                StartTime = $proc.StartTime.ToString("o")
            }
        }
    }
    return $out
}

