function Enable-DistributeFilesFeature {
    param([string]$RegBasePath)

    $featuresPath = if ($RegBasePath -match '^\\\\') {
        $RegBasePath -replace '^\\\\([^\\]+)\\(.+)$', '$2'
    } else {
        $RegBasePath -replace '^HKLM\\', 'HKLM:\'
    }
    $featuresPath = Join-Path $featuresPath "Features"

    if ($RegBasePath -match '^\\\\([^\\]+)\\') {
        $machine = $Matches[1]
        $base = [Microsoft.Win32.RegistryKey]::OpenRemoteBaseKey('LocalMachine', $machine)
        $sub = $base.OpenSubKey('SOFTWARE\Veyon Solutions\Veyon\Features', $true)
        if (-not $sub) {
            Write-Host "  Chave Features ausente em $RegBasePath" -ForegroundColor Yellow
            $base.Close()
            return
        }
        $current = @($sub.GetValue('DisabledFeatures'))
        $filtered = [string[]]($current | Where-Object { $_ -and $_ -ne $DistributeFilesUid })
        if ($filtered.Count -eq $current.Count) {
            Write-Host "  DistributeFiles ja habilitado em $RegBasePath" -ForegroundColor DarkGray
        } else {
            $sub.SetValue('DisabledFeatures', $filtered, 'MultiString')
            Write-Host "  DistributeFiles HABILITADO em $RegBasePath" -ForegroundColor Green
        }
        $sub.Close(); $base.Close()
        return
    }

