function Convert-MdToPdf([string]$MdPath) {
    $base = [System.IO.Path]::GetFileNameWithoutExtension($MdPath)
    $htmlPath = Join-Path $env:TEMP "cimed-$base.html"
    $pdfPath = Join-Path $DocsDir "$base.pdf"
    $pyScript = Join-Path $env:TEMP "cimed-md2html-$base.py"
    $cssPath = Join-Path $env:TEMP "cimed-$base.css"
    Get-ReportCss $base | Set-Content -Path $cssPath -Encoding UTF8

    @"
import pathlib, markdown, re, html as htmlmod
md_path = pathlib.Path(r"$MdPath")
html_path = pathlib.Path(r"$htmlPath")
css_path = pathlib.Path(r"$cssPath")
base = md_path.stem
text = md_path.read_text(encoding='utf-8')
docs = md_path.parent

def repl_img(match):
    alt, path = match.group(1), match.group(2)
    if path.startswith('http'):
        return match.group(0)
    uri = (docs / path).resolve().as_uri()
    return '![%s](%s)' % (alt, uri)

text = re.sub(r'!\[([^\]]*)\]\(([^)]+)\)', repl_img, text)

def repl_html_img_src(match):
    tag = match.group(0)
    src_m = re.search(r'src=["\']([^"\']+)["\']', tag, re.I)
    if not src_m:
        return tag
    path = src_m.group(1)
    if path.startswith('http'):
        return tag
    uri = (docs / path).resolve().as_uri()
    return tag.replace(path, uri)

text = re.sub(r'<img[^>]+/?>', repl_html_img_src, text, flags=re.I)
text = re.sub(
    r'<p align="center">\s*<img ([^>]+)/>\s*</p>\s*<p align="center"><em>([^<]+)</em></p>',
    lambda m: '<figure><img %s/><figcaption>%s</figcaption></figure>' % (m.group(1), htmlmod.escape(m.group(2))),
    text,
    flags=re.I
)
body = markdown.markdown(
    text,
    extensions=['tables', 'fenced_code', 'nl2br', 'sane_lists']
)
css = css_path.read_text(encoding='utf-8')
extra = '''
figure { text-align: center; margin: 14px 0 18px; page-break-inside: avoid; }
figcaption { color: #475569; font-size: 9pt; margin-top: 6px; font-style: italic; }
p[align="center"] { text-align: center; }
'''
html_doc = (
    '<!DOCTYPE html><html lang="pt-BR"><head><meta charset="utf-8">'
    '<title>' + htmlmod.escape(base) + '</title>'
    '<style>' + css + extra + '</style></head><body>' + body + '</body></html>'
)
html_path.write_text(html_doc, encoding='utf-8')
"@ | Set-Content -Path $pyScript -Encoding UTF8

    python $pyScript
    if (-not (Test-Path $htmlPath)) { throw "HTML nao gerado: $htmlPath" }

    if (Test-Path $pdfPath) { Remove-Item $pdfPath -Force }
    $uri = ([System.Uri]$htmlPath).AbsoluteUri
    & $edge --headless --disable-gpu --no-pdf-header-footer --print-to-pdf="$pdfPath" $uri | Out-Null
    $deadline = (Get-Date).AddSeconds(30)
    while (-not (Test-Path $pdfPath) -and (Get-Date) -lt $deadline) {
        Start-Sleep -Milliseconds 500
    }
    if (-not (Test-Path $pdfPath)) { throw "Falha ao gerar $pdfPath" }
    Write-Host "OK $pdfPath"
}

foreach ($name in @(
    "RELATORIO-TECNICO-PROJETO-CIMED.md",
    "RELATORIO-ESTRUTURA-CODIGO-CIMED.md"
)) {
    $md = Join-Path $DocsDir $name
    if (-not (Test-Path $md)) { throw "Arquivo nao encontrado: $md" }
    Convert-MdToPdf $md
}

