    -Execute "powershell.exe" `
    -Argument "-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File `"$destScript`" -Quiet"

$startOnce = (Get-Date).Date.AddMinutes(5)
if ($startOnce -lt (Get-Date)) {
    $startOnce = (Get-Date).AddMinutes(2)
}

$triggers = @(
    (New-ScheduledTaskTrigger -AtStartup),
    (New-ScheduledTaskTrigger -Once -At $startOnce -RepetitionInterval (New-TimeSpan -Minutes 30) -RepetitionDuration (New-TimeSpan -Days 3650))
)

$settings = New-ScheduledTaskSettingsSet `
    -AllowStartIfOnBatteries `
    -DontStopIfGoingOnBatteries `
    -StartWhenAvailable `
    -ExecutionTimeLimit (New-TimeSpan -Minutes 5) `
    -MultipleInstances IgnoreNew

$principal = New-ScheduledTaskPrincipal -UserId "SYSTEM" -LogonType ServiceAccount -RunLevel Highest

Unregister-ScheduledTask -TaskName $TaskName -Confirm:$false -ErrorAction SilentlyContinue
Register-ScheduledTask -TaskName $TaskName -Action $action -Trigger $triggers -Settings $settings -Principal $principal -Force | Out-Null

try {
    $task = Get-ScheduledTask -TaskName $TaskName
    $boot = @($task.Triggers | Where-Object { $_.CimClass.CimClassName -match "Boot" }) | Select-Object -First 1
    if ($boot) {
        $boot.Delay = "PT2M"
        Set-ScheduledTask -InputObject $task | Out-Null
    }
} catch {
    Write-Msg "Aviso: nao foi possivel setar Delay PT2M ($($_.Exception.Message))" "Yellow"
}

