# Deixa Veyon_Custom com layout do instalador oficial (sem .bak, runtime ou staging na raiz)
param(
    [string]$CustomDir = (Join-Path (Split-Path -Parent $PSScriptRoot) "Veyon_Custom")
)

$ErrorActionPreference = "Stop"
if (-not (Test-Path $CustomDir)) { throw "Pasta nao encontrada: $CustomDir" }

$archive = Join-Path $CustomDir "_archive"
$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backupDir = Join-Path $archive "backups-$stamp"
New-Item -ItemType Directory -Path $backupDir -Force | Out-Null

$moved = @()

Get-ChildItem $CustomDir -File -Force | Where-Object { $_.Name -match '\.bak' } | ForEach-Object {
    Move-Item $_.FullName $backupDir -Force
    $moved += $_.Name
}

foreach ($name in @("acessos_integrity_state.txt")) {
    $path = Join-Path $CustomDir $name
    if (Test-Path $path) {
        $runtimeDir = Join-Path $archive "runtime"
        New-Item -ItemType Directory -Path $runtimeDir -Force | Out-Null
        $target = Join-Path $runtimeDir $name
        if (Test-Path $target) { Remove-Item $target -Force }
        Move-Item $path $target -Force
        $moved += $name
    }
}

Get-ChildItem $CustomDir -File -Force | Where-Object { $_.Name -like "debug-*.md" -or $_.Name -like "relatorio-*.md" -or $_.Name -like "qtdebug-*.txt" } | ForEach-Object {
    Move-Item $_.FullName $backupDir -Force
    $moved += $_.Name
}

foreach ($dirName in @("_deploy_logs_network_only")) {
    $path = Join-Path $CustomDir $dirName
    if (Test-Path $path) {
        $target = Join-Path $archive "$dirName-$stamp"
        Move-Item $path $target -Force
        $moved += "$dirName/ -> _archive/"
    }
}

if ($moved.Count -eq 0) {
    Write-Host "OK: $CustomDir ja esta limpo (layout oficial)." -ForegroundColor Green
    if (Test-Path $backupDir) {
        $left = Get-ChildItem $backupDir -Force -ErrorAction SilentlyContinue
        if (-not $left) { Remove-Item $backupDir -Force -ErrorAction SilentlyContinue }
    }
} else {
    Write-Host "Limpeza concluida em $CustomDir" -ForegroundColor Green
    $moved | ForEach-Object { Write-Host "  -> $_" }
    Write-Host "Backups em: $backupDir" -ForegroundColor Cyan
}

$rootFiles = Get-ChildItem $CustomDir -File -Force | Select-Object -ExpandProperty Name
$bad = $rootFiles | Where-Object { $_ -match '\.bak$|\.bak-|integrity_state|debug-|relatorio-' }
if ($bad) {
    throw "Ainda ha artefatos na raiz: $($bad -join ', ')"
}

foreach ($logSub in @("acessos_veyon", "acessos_veyon_ad")) {
    $logDir = Join-Path $CustomDir "logs\$logSub"
    if (-not (Test-Path $logDir)) {
        New-Item -ItemType Directory -Path $logDir -Force | Out-Null
        Write-Host "Criada pasta vazia: logs\$logSub"
    }
    Get-ChildItem $logDir -Force -ErrorAction SilentlyContinue |
        Where-Object { -not $_.PSIsContainer } |
        ForEach-Object {
            $runtimeDir = Join-Path $archive "runtime"
            New-Item -ItemType Directory -Path $runtimeDir -Force | Out-Null
            Move-Item $_.FullName $runtimeDir -Force
            $moved += "logs\$logSub\$($_.Name)"
        }
}

Write-Host "`nRaiz pronta para instalacao (estilo veyon.io):" -ForegroundColor Cyan
Get-ChildItem $CustomDir -Force | Where-Object { $_.Name -notlike "_archive" } |
    Select-Object Name, @{N="Tipo";E={ if ($_.PSIsContainer) { "pasta" } else { "arquivo" } }} |
    Format-Table -AutoSize

