# Valida integridade SHA-256 dos logs CIMED (mesma regra do AccessLogWriter.cpp)
param(
    [string]$LogPath = "",
    [switch]$Network,
    [switch]$Local
)

$HashMarker = " | SHA256: "

function Test-AccessLogFile {
    param([string]$Path, [string]$Label)

    Write-Host "`n=== $Label ===" -ForegroundColor Cyan
    Write-Host "Path: $Path"

    if (-not (Test-Path -LiteralPath $Path)) {
        Write-Host "ARQUIVO NAO EXISTE" -ForegroundColor Yellow
        return @{ exists = $false }
    }

    $bytes = [System.IO.File]::ReadAllBytes($Path)
    $nonZero = @($bytes | Where-Object { $_ -ne 0 }).Count
    Write-Host "Tamanho: $($bytes.Length) bytes | bytes nao-nulos: $nonZero"

    if ($nonZero -eq 0 -and $bytes.Length -gt 0) {
        Write-Host "CORROMPIDO: arquivo inteiro preenchido com zeros (0x00)" -ForegroundColor Red
        return @{ exists = $true; corrupted = $true; valid = 0; invalid = 0 }
    }

    $text = [System.Text.Encoding]::UTF8.GetString($bytes)
    if ($text.StartsWith([char]0xFEFF)) { $text = $text.Substring(1) }
    $text = $text -replace "`r`n", "`n" -replace "`r", "`n"

    $lineNum = 0
    $valid = 0
    $invalid = @()

    foreach ($rawLine in ($text -split "`n")) {
        $line = $rawLine.Trim()
        if ($line -eq "") { continue }
        $lineNum++

        $idx = $line.LastIndexOf($HashMarker)
        if ($idx -lt 0) {
            $invalid += "$lineNum (sem SHA256)"
            continue
        }

        $message = $line.Substring(0, $idx)
        $stored = $line.Substring($idx + $HashMarker.Length).Trim()
        $sha = [System.Security.Cryptography.SHA256]::Create()
        $expected = ([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($message))).Replace("-", "").ToLower())

        if ($stored.ToLower() -ne $expected) {
            $invalid += "$lineNum (hash invalido)"
        } else {
            $valid++
        }
    }

    Write-Host "Linhas com conteudo: $lineNum | validas: $valid | invalidas: $($invalid.Count)"

    if ($invalid.Count -gt 0) {
        Write-Host "Problemas (ate 10):" -ForegroundColor Red
        $invalid | Select-Object -First 10 | ForEach-Object { Write-Host "  - $_" }
    } elseif ($lineNum -gt 0) {
        Write-Host "Integridade OK" -ForegroundColor Green
    }

    if ($lineNum -gt 0) {
        $lastLines = @($text -split "`n" | Where-Object { $_.Trim() -ne "" })
        Write-Host "Ultima linha:"
        $last = $lastLines[-1]
        if ($last.Length -gt 180) { $last = $last.Substring(0, 180) + "..." }
        Write-Host "  $last"
    }

    return @{ exists = $true; corrupted = $false; valid = $valid; invalid = $invalid.Count; lines = $lineNum }
}

$results = @()

if ($LogPath) {
