function Get-Sha256Hex([string]$Message) {
    $sha = [System.Security.Cryptography.SHA256]::Create()
    return ([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($Message))).Replace("-", "").ToLower())
}

function Test-LogLine([string]$Line) {
    $idx = $Line.LastIndexOf($HashMarker)
    if ($idx -lt 0) { return $false }
    $msg = $Line.Substring(0, $idx)
    $stored = $Line.Substring($idx + $HashMarker.Length).Trim()
    return ($stored.ToLower() -eq (Get-Sha256Hex $msg))
}

