# Teste rigoroso: unicidade, loopback e par conexao/desconexao em acessos_veyon
param(
    [switch]$Baseline,
    [switch]$After,
    [switch]$Compare,
    [string]$SessionId = ""
)

$ErrorActionPreference = "Stop"
$HashMarker = " | SHA256: "
$NetAccessLog = "\\172.20.100.36\vnc_veyon$\veyon\acessos_veyon\acessos_veyon.log"
$SessionRoot = Join-Path (Split-Path -Parent (Split-Path -Parent $MyInvocation.MyCommand.Path)) "dist\debug-log-sessions"

function Get-Sha256Hex([string]$Message) {
    $sha = [System.Security.Cryptography.SHA256]::Create()
    return ([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($Message))).Replace("-", "").ToLower()
}

function Parse-AccessLogSnapshot([string]$Path) {
    $snap = [ordered]@{
        path = $Path
        exists = $false
        lineCount = 0
        conexoes = @()
        desconexoes = @()
        loopbackLines = @()
        invalidHash = @()
    }

    if (-not (Test-Path -LiteralPath $Path)) { return $snap }

    $bytes = [System.IO.File]::ReadAllBytes($Path)
    $text = [System.Text.Encoding]::UTF8.GetString($bytes)
    if ($text.StartsWith([char]0xFEFF)) { $text = $text.Substring(1) }
    $text = $text -replace "`r`n", "`n" -replace "`r", "`n"
    $lines = @($text -split "`n" | Where-Object { $_.Trim() -ne "" })

    $snap.exists = $true
    $snap.lineCount = $lines.Count

    foreach ($line in $lines) {
        $plain = $line
        $idx = $line.LastIndexOf($HashMarker)
        if ($idx -ge 0) {
            $plain = $line.Substring(0, $idx)
            $stored = $line.Substring($idx + $HashMarker.Length).Trim()
            if ($stored.ToLower() -ne (Get-Sha256Hex $plain)) {
                $snap.invalidHash += $line
            }
        } else {
            $snap.invalidHash += $line
        }

        if ($plain -match "127\.0\.0\.1|::1|\(localhost\)") {
            $snap.loopbackLines += $plain
        }

        if ($plain -match "acesso remoto via Veyon") {
            $snap.conexoes += $plain
        } elseif ($plain -match "encerramento da conex") {
            $snap.desconexoes += $plain
        }
    }

    return $snap
}

function Assert-True([bool]$Cond, [string]$Msg) {
    if (-not $Cond) { throw "FALHOU: $Msg" }
    Write-Host "OK: $Msg" -ForegroundColor Green
}

function Save-Phase([string]$Name, [string]$Dir) {
    $payload = [ordered]@{
        phase = $Name
        capturedAt = (Get-Date).ToString("o")
        hostname = $env:COMPUTERNAME
        networkAccess = Parse-AccessLogSnapshot -Path $NetAccessLog
    }
    $out = Join-Path $Dir "$Name.json"
    $payload | ConvertTo-Json -Depth 6 | Set-Content -Path $out -Encoding UTF8
    return $payload
}

function Compare-Snapshots($Before, $After) {
    Write-Host "`n=== TESTE RIGOROSO LOGS (UNICIDADE + LOOPBACK) ===" -ForegroundColor Cyan
    Write-Host "Maquina: $($After.hostname)"
    Write-Host "Log: $NetAccessLog"

    $bConn = @($Before.networkAccess.conexoes).Count
    $bDisc = @($Before.networkAccess.desconexoes).Count
    $aConn = @($After.networkAccess.conexoes).Count
    $aDisc = @($After.networkAccess.desconexoes).Count
    $newConn = $aConn - $bConn
    $newDisc = $aDisc - $bDisc

    Write-Host "`nDelta: +$newConn conexao(oes), +$newDisc desconexao(oes)"

    Assert-True ($newConn -le 1) "No maximo 1 nova linha de conexao por sessao de teste"
    Assert-True ($newDisc -le 1) "No maximo 1 nova linha de desconexao por sessao de teste"

    if ($newConn -ge 1 -and $newDisc -ge 1) {
        Assert-True ($newConn -eq $newDisc) "Par 1:1 conexao/desconexao no delta do teste"
    } elseif ($newConn -ge 1) {
        throw "FALHOU: conexao registrada sem desconexao correspondente no teste"
    }

    $loopbackTotal = @($After.networkAccess.loopbackLines).Count
    Assert-True ($loopbackTotal -eq 0) "Nenhuma linha com 127.0.0.1/loopback em acessos_veyon ($loopbackTotal encontrada(s))"

    $badHash = @($After.networkAccess.invalidHash).Count
    Assert-True ($badHash -eq 0) "Todas as linhas possuem SHA256 valido"

    if ($newConn -ge 1) {
        $lastConn = $After.networkAccess.conexoes[-1]
        Write-Host "`nUltima conexao:" -ForegroundColor Yellow
        Write-Host "  $lastConn"
    }
    if ($newDisc -ge 1) {
        $lastDisc = $After.networkAccess.desconexoes[-1]
        Write-Host "`nUltima desconexao:" -ForegroundColor Yellow
        Write-Host "  $lastDisc"
    }

    Write-Host "`n=== TESTE APROVADO ===" -ForegroundColor Green
}

