constexpr int CaptureDelayMs = 400;

void grabDialog( QDialog* dialog, const QString& outputPath )
{
	dialog->setAttribute( Qt::WA_DontShowOnScreen, false );
	dialog->show();
	dialog->raise();
	dialog->activateWindow();
	QApplication::processEvents();
	QGuiApplication::sync();

	const auto geometry = dialog->frameGeometry();
	const auto pixmap = dialog->screen()->grabWindow( 0,
													  geometry.x(),
													  geometry.y(),
													  geometry.width(),
													  geometry.height() );
	pixmap.save( outputPath );
	dialog->close();
}

void captureLogon( const QString& outputDir )
{
	PasswordDialog dialog;
	if( auto* username = dialog.findChild<QLineEdit*>( QString(), Qt::FindDirectChildrenOnly ) )
	{
		Q_UNUSED( username )
	}

	dialog.findChild<QLineEdit*>( QStringLiteral( "username" ) );
	for( auto* edit : dialog.findChildren<QLineEdit*>() )
	{
		if( edit->echoMode() == QLineEdit::Password )
		{
			edit->setText( QStringLiteral( "********" ) );
		}
	}

	const auto edits = dialog.findChildren<QLineEdit*>();
	if( edits.size() >= 2 )
	{
		edits.at( 0 )->setText( QStringLiteral( "professor.cimed" ) );
		edits.at( 1 )->setText( QStringLiteral( "********" ) );
	}

	grabDialog( &dialog, QDir( outputDir ).filePath( QStringLiteral( "tela-logon-veyon.png" ) ) );
}

void captureRemoteHost( const QString& outputDir )
{
	CimedHostInputDialog dialog;
	for( auto* edit : dialog.findChildren<QLineEdit*>() )
	{
		edit->setText( QStringLiteral( "172.20.100.50" ) );
	}

	grabDialog( &dialog, QDir( outputDir ).filePath( QStringLiteral( "tela-acesso-remoto-hostname.png" ) ) );
}

void captureDesktopConfirm( const QString& outputDir )
{
	DesktopAccessConfirmDialog dialog( QStringLiteral( "professor.cimed" ),
									   QStringLiteral( "LAB-PC-042" ) );
	grabDialog( &dialog, QDir( outputDir ).filePath( QStringLiteral( "tela-confirmar-desktop.png" ) ) );
}

void captureSupportInfo( const QString& outputDir )
{
	ComputerSupportInfoDialog dialog;
	grabDialog( &dialog, QDir( outputDir ).filePath( QStringLiteral( "tela-f9-informacoes.png" ) ) );
}

