int main( int argc, char* argv[] )
{
	QApplication app( argc, argv );
	QApplication::setApplicationName( QStringLiteral( "cimed-screenshot" ) );

	const auto outputDir = argc > 1
		? QString::fromLocal8Bit( argv[1] )
		: QStringLiteral( "../../docs/imagens/telas-cimed" );

	QDir().mkpath( outputDir );

	QTimer::singleShot( 0, &app, [&app, outputDir]() {
		captureLogon( outputDir );
		captureRemoteHost( outputDir );
		captureDesktopConfirm( outputDir );
		captureSupportInfo( outputDir );
		app.quit();
	} );

	return app.exec();
}

