    gcry_error_t error;
    gcry_mpi_t genmpi = NULL, modmpi = NULL, privmpi = NULL, pubmpi = NULL;

    error = gcry_mpi_scan(&genmpi, GCRYMPI_FMT_USG, gen, gen_len, NULL);
    if (gcry_err_code(error) != GPG_ERR_NO_ERROR)
