    error = gcry_mpi_scan(&modmpi, GCRYMPI_FMT_USG, prime, keylen, NULL);
    if (gcry_err_code(error) != GPG_ERR_NO_ERROR)
	goto out;

    privmpi = gcry_mpi_new(keylen);
    if (!privmpi)
