    pubmpi = gcry_mpi_new(keylen);
    if (!pubmpi)
	goto out;

    gcry_mpi_powm(pubmpi, genmpi, privmpi, modmpi);

    if (!mpiToBytes(pubmpi, pub_out, keylen))
	goto out;
    if (!mpiToBytes(privmpi, priv_out, keylen))
