    uint8_t *greenTable = redTable + 3*(in->redMax + 1);
    uint8_t *blueTable = greenTable + 3*(in->greenMax + 1);
    uint32_t outValue,inValue;
    int shift = rfbEndianTest?0:8;

    while (height > 0) {
        opLineEnd = op+3*width;

        while (op < opLineEnd) {
	    inValue = ((*(uint32_t *)ip)>>shift)&0x00ffffff;
