#if BPP!=8
      if( zywrle_level & 0x80 ){
	    zywrle_level &= 0x7F;
		ZYWRLE_SYNTHESIZE( buf, buf, tw, th, tw, zywrle_level, zywrleBuf );
	  }
#endif
      IMAGE_RECT(tx,ty,tw,th,buf);
	   if (initialupdate_counter < 4) if (!directx_used)InvalidateRect(m_hwndcn, NULL, FALSE);
    }
  }

  zis->reset();
}

