         // Call the exit function
		   // If the app failed to hook OK, ExitInstance will still operate OK (hopefully...)
		   ExitInstance();
		   if (g_shdata) UnmapViewOfFile(g_shdata);
		   if (filemapping)CloseHandle(filemapping);
      }
      isAttached = FALSE;

		return TRUE;

	default:
		return TRUE;
	}
}

