		loadDllFromMemory->loadDDengine( StartW8,  StartW8V2,  StopW8,  LockW8,  UnlockW8,  ShowCursorW8,  HideCursorW8);
		if (StartW8 == NULL || StopW8 == NULL || LockW8 == NULL || UnlockW8 == NULL || ShowCursorW8 == NULL || HideCursorW8 == NULL)
