mini_lock::mini_lock(int lockcode)
{
	preventDeadlock = 0;
	while (g_lockcode != 0) {

		Sleep(100);
		preventDeadlock++;
		if (preventDeadlock > 20)
			g_lockcode = 0;
	}
	g_lockcode = lockcode;
}

mini_lock::~mini_lock()
{
	g_lockcode = 0;
}


