	unsigned char Invalue=12;
	unsigned char Outvalue=0;
	if (StarteventFn == NULL)
		goto error;
	int StartErrorCounter = 0;
	while (Invalue!=Outvalue) {
		StarteventFn->Call_Fnction_Long_Timeout((char*)&Invalue,(char*)&Outvalue, 1);
