VideoDriver::~VideoDriver()
{
	if (osVer == OSWINXP) {
		mirror_driver_detach_XP();
		if (pSharedMemory != NULL) videoMemory_ReleaseSharedMemory(pSharedMemory);
	}
	if (osVer == OSVISTA) {
		mirror_driver_Vista(0, 0, 0, 0, 0);
		if (pSharedMemory != NULL) videoMemory_ReleaseSharedMemory(pSharedMemory);
	}	
}
//----------------------------------------------------------
void VideoDriver::videoDriver_start(int x, int y, int w, int h, bool onlyVirtual, int maxFPS)
{
	if (init)
		return;
	blocked = true;
	oldAantal = 1;
	pSharedMemory = NULL;
	if (osVer == OSWINXP) {
		if (mirror_driver_attach_XP(x, y, w, h)) {
			if (getDcMirror() != NULL) {
				pSharedMemory = videoMemory_GetSharedMemory();
				pChangebuf = (PCHANGES_BUF)pSharedMemory;
				pFramebuffer = pSharedMemory + sizeof(CHANGES_BUF);
			}
			else {
				pSharedMemory = NULL;
			}
		}
		else
			pSharedMemory = NULL;
	}

	if (osVer == OSVISTA) {
		if (mirror_driver_Vista(1, x, y, w, h)) {
			if (getDcMirror() != NULL) {
				pSharedMemory = videoMemory_GetSharedMemory();
				pChangebuf = (PCHANGES_BUF)pSharedMemory;
				pFramebuffer = pSharedMemory + sizeof(CHANGES_BUF);
			}
			else {
				if (mirror_driver_attach_XP(x, y, w, h)) {
					if (getDcMirror() != NULL) {
						pSharedMemory = videoMemory_GetSharedMemory();
						pChangebuf = (PCHANGES_BUF)pSharedMemory;
						pFramebuffer = pSharedMemory + sizeof(CHANGES_BUF);
					}
					else
						pSharedMemory = NULL;
				}
				else
					pSharedMemory = NULL;
			}
		}
		else
			pSharedMemory = NULL;
	}
	blocked = false;
}
