void VideoDriver::videoDriver_Stop()
{
	if (init)
		return;
	if (osVer == OSWINXP) {
		mirror_driver_detach_XP();
		if (pSharedMemory != NULL) videoMemory_ReleaseSharedMemory(pSharedMemory);
	}
	if (osVer == OSVISTA) {
		mirror_driver_Vista(0, 0, 0, 0, 0);
		if (pSharedMemory != NULL) videoMemory_ReleaseSharedMemory(pSharedMemory);
	}
	pSharedMemory = NULL;
	pChangebuf = NULL;
	pFramebuffer = NULL;
}
