#ifdef _DEBUG

					OutputDevMessage("SCHook changeRct %i %i %i %i  \n",rect.tl.x,rect.br.x,rect.tl.y,rect.br.y);	
#endif
					returnvalue=true;
					rgncache.assign_union(rect);
				}
			}			
		}
		for (i=1;i<=counter;i++)
		{
			if (ringbuffer->type[i]==0 )
			{
				rfb::Rect rect;
				rect.tl = rfb::Point(ringbuffer->rect1[i].left, ringbuffer->rect1[i].top);
