	vncDesktop *mydesk=(vncDesktop*)lpParam;
	//if (mydesk->m_server->Win8HelperEnabled()) 
		//keybd_initialize();
	mydesk->InitWindow();
	if (settings->getEnableWin8Helper())
		keybd_delete();
	return 0;
}

