// The class methods
vncInstHandler::vncInstHandler()
{
	mutex=NULL;
}

vncInstHandler::~vncInstHandler()
{
	if (mutex)
	{
		ReleaseMutex(mutex);
		CloseHandle (mutex);
	}
}

BOOL
vncInstHandler::Init()
{
	// Create the named mutex
	mutex = CreateMutex(NULL, FALSE, mutexname);
	if (mutex == NULL)
		return FALSE;

	// Check that the mutex didn't already exist
	if (GetLastError() == ERROR_ALREADY_EXISTS)
		return FALSE;

	return TRUE;
}

