void AccessLogRecorder::logOutboundAccessSuccess( const QString& destinationHost,
												  const QString& destinationIp )
{
	const auto originIp = localIpv4();
	const auto originHost = ComputerSupportInfo::hostname();

	if( shouldRecordAccess( originIp, destinationIp ) == false )
	{
		return;
	}

	const auto dataHora = QDateTime::currentDateTime().toString( QStringLiteral( "dd/MM/yyyy 'às' HH:mm:ss" ) );
	const auto mensagem = QStringLiteral(
		"Em %1 foi identificado acesso remoto via Veyon originado do equipamento %2 (%3) para o equipamento %4 (%5), utilizando a conta %6. O acesso foi %7." )
			.arg( dataHora,
				  originHost,
				  originIp,
				  destinationHost,
				  destinationIp,
				  ComputerSupportInfo::adUserName(),
				  QStringLiteral( "concluído com sucesso" ) );

	AccessLogWriter::appendAccessLogMessage( mensagem );
}

void AccessLogRecorder::logOutboundDisconnect( const QString& destinationHost,
											   const QString& destinationIp,
											   qint64 elapsedMilliseconds )
{
	const auto originIp = localIpv4();
	const auto originHost = ComputerSupportInfo::hostname();

	if( shouldRecordAccess( originIp, destinationIp ) == false )
	{
		return;
	}

	const auto dataHora = QDateTime::currentDateTime().toString( QStringLiteral( "dd/MM/yyyy 'às' HH:mm:ss" ) );
	const auto mensagem = QStringLiteral(
		"Em %1 foi identificado encerramento da conexão via Veyon originado do %2 (%3) para o equipamento %4 (%5), utilizando a conta %6 com um tempo de conexao de %7." )
			.arg( dataHora,
				  originHost,
				  originIp,
				  destinationHost,
				  destinationIp,
				  ComputerSupportInfo::adUserName(),
				  formatDisconnectDuration( elapsedMilliseconds ) );

	AccessLogWriter::appendAccessLogMessage( mensagem );
}

