QString firstNonLoopbackIpv4()
{
	for( const auto& address : QNetworkInterface::allAddresses() )
	{
		if( address.protocol() == QAbstractSocket::IPv4Protocol && address.isLoopback() == false )
		{
			return address.toString();
		}
	}

	return {};
}

QString localHostName()
{
	const auto hostName = QHostInfo::localHostName();
	return hostName.isEmpty() ? QStringLiteral( "desconhecido" ) : hostName;
}

QString localIpAddress()
{
	const auto ipAddress = firstNonLoopbackIpv4();
	return ipAddress.isEmpty() ? QStringLiteral( "desconhecido" ) : ipAddress;
}

QString currentAdUserLogin()
{
	// Tamper alerts run inside veyon-server (Session 0). Prefer the active Console
	// interactive user — same approach as CimedVersionCompatibility version alerts.
#ifdef Q_OS_WIN
	auto loginName = accessLogLookupLocalInteractiveUser();
	if( loginName.isEmpty() )
	{
		loginName = accessLogLookupRemoteInteractiveUser( localHostName() );
	}
	if( loginName.isEmpty() )
	{
		const auto host = localHostName();
		if( host.contains( QLatin1Char( '.' ) ) )
		{
			loginName = accessLogLookupRemoteInteractiveUser(
				host.section( QLatin1Char( '.' ), 0, 0 ) );
		}
	}
	if( loginName.isEmpty() )
	{
		loginName = accessLogLookupRemoteInteractiveUser( firstNonLoopbackIpv4() );
	}
	if( loginName.isEmpty() == false )
	{
		return loginName;
	}
#endif

	const auto processLoginName = VeyonCore::platform().userFunctions().queryCurrentUserProperty(
		PlatformUserFunctions::UserProperty::LoginName );
	return processLoginName.isEmpty() ? QStringLiteral( "desconhecido" ) : processLoginName;
}

QString currentAdUserFullName()
{
	const auto loginName = currentAdUserLogin();

#ifdef Q_OS_WIN
	if( loginName != QStringLiteral( "desconhecido" ) )
	{
		const auto ldapFullName = accessLogLookupDomainUserDisplayName( loginName );
		if( ldapFullName.isEmpty() == false )
		{
			return ldapFullName;
		}
	}
#endif

	const auto fullName = VeyonCore::platform().userFunctions().queryCurrentUserProperty(
		PlatformUserFunctions::UserProperty::FullName );
	if( fullName.isEmpty() == false )
	{
		return fullName;
	}

	return QStringLiteral( "desconhecido" );
}

struct TamperActorContext
{
	QString host;
	QString ip;
	QString login;
	QString displayName;
};

QString stripAccessLogHashMarker( const QString& line )
{
	const auto markerIndex = line.lastIndexOf( QStringLiteral( " | SHA256: " ) );
	if( markerIndex < 0 )
	{
		return line.trimmed();
	}

	return line.left( markerIndex ).trimmed();
}

// Attribute alert to the origin of the latest Veyon access/disconnect line (who likely
// edited the share), not the detector host that won the claim race.
TamperActorContext resolveTamperActorFromAccessLog( const QString& accessLogContent )
{
	TamperActorContext actor;

	static const QRegularExpression originRe(
		QStringLiteral(
			"originado do (?:equipamento )?([^\\s(]+)\\s*\\(([^)]+)\\)"
			".*utilizando a conta (.+?)(?:\\. O acesso| com um tempo)" ),
		QRegularExpression::DotMatchesEverythingOption | QRegularExpression::CaseInsensitiveOption );

	const auto lines = accessLogContent.split( QLatin1Char( '\n' ), Qt::SkipEmptyParts );
	for( auto it = lines.crbegin(); it != lines.crend(); ++it )
	{
		const auto message = stripAccessLogHashMarker( *it );
		if( message.isEmpty() )
		{
			continue;
		}

		const auto match = originRe.match( message );
		if( match.hasMatch() == false )
		{
			continue;
		}

		actor.host = match.captured( 1 ).trimmed();
		actor.ip = match.captured( 2 ).trimmed();
		actor.login = match.captured( 3 ).trimmed();
		break;
	}

#ifdef Q_OS_WIN
	if( actor.host.isEmpty() == false || actor.ip.isEmpty() == false )
	{
		auto consoleUser = accessLogLookupRemoteInteractiveUser( actor.host );
		if( consoleUser.isEmpty() && actor.host.contains( QLatin1Char( '.' ) ) )
		{
			consoleUser = accessLogLookupRemoteInteractiveUser(
				actor.host.section( QLatin1Char( '.' ), 0, 0 ) );
		}
		if( consoleUser.isEmpty() )
		{
			consoleUser = accessLogLookupRemoteInteractiveUser( actor.ip );
		}
		if( consoleUser.isEmpty() == false )
		{
			actor.login = consoleUser;
		}
	}

	if( actor.login.isEmpty() == false &&
		actor.login != QStringLiteral( "desconhecido" ) )
	{
		actor.displayName = accessLogLookupDomainUserDisplayName( actor.login );
	}
#endif

	if( actor.host.isEmpty() )
	{
		actor.host = localHostName();
	}
	if( actor.ip.isEmpty() )
	{
		actor.ip = localIpAddress();
	}
	if( actor.login.isEmpty() )
	{
		actor.login = currentAdUserLogin();
	}
	if( actor.displayName.isEmpty() )
	{
		if( actor.login == currentAdUserLogin() )
		{
			actor.displayName = currentAdUserFullName();
		}
		else
		{
#ifdef Q_OS_WIN
			actor.displayName = accessLogLookupDomainUserDisplayName( actor.login );
#endif
			if( actor.displayName.isEmpty() )
			{
				actor.displayName = QStringLiteral( "desconhecido" );
			}
		}
	}

	return actor;
}

QString integrityStateFilePath()
{
	return QDir( QCoreApplication::applicationDirPath() ).filePath( QStringLiteral( "acessos_integrity_state.txt" ) );
}

QHash<QString, QString> loadIntegrityState()
{
	QHash<QString, QString> state;

	QFile file( integrityStateFilePath() );
	if( file.open( QIODevice::ReadOnly | QIODevice::Text ) == false )
	{
		return state;
	}

	QTextStream in( &file );
	in.setEncoding( QStringConverter::System );

	while( in.atEnd() == false )
	{
		const auto line = in.readLine().trimmed();
		const auto separatorIndex = line.indexOf( QLatin1Char( '=' ) );
		if( separatorIndex <= 0 )
		{
			continue;
		}

		state.insert( line.left( separatorIndex ), line.mid( separatorIndex + 1 ) );
	}

	return state;
}

