	} );
	buttonsRow->addWidget( connectButton );

	auto* cancelButton = CimedDialogStyle::createSecondaryButton( contentPanel, tr( "CANCELAR" ) );
	connect( cancelButton, &QPushButton::clicked, this, &QDialog::reject );
	buttonsRow->addWidget( cancelButton );
	buttonsRow->addStretch();

	contentLayout->addLayout( buttonsRow );
	contentLayout->addStretch();

	connect( m_hostEdit, &QLineEdit::returnPressed, this, [this]() {
		m_hostAddress = m_hostEdit->text().trimmed();
		accept();
	} );

	m_hostEdit->setFocus();
}

