int versionAlertDialogHeight( const QLabel& policyLabel,
							  const QLabel& detailsLabel,
							  int contentWidth,
							  int minimumHeight )
{
	const QFontMetrics policyMetrics( policyLabel.font() );
	const auto policyHeight = policyMetrics.boundingRect( QRect( 0, 0, contentWidth, 0 ),
														  Qt::TextWordWrap,
														  policyLabel.text() ).height();
	const auto detailsHeight = qMax( detailsLabel.heightForWidth( contentWidth ),
									 detailsLabel.sizeHint().height() );
	const auto contentHeight = 28 + policyHeight + 12 + detailsHeight + 12 + 52 + 20;
	const auto totalHeight = 54 + contentHeight + 44;
	const auto screen = QGuiApplication::primaryScreen();
	const auto maxHeight = screen ? screen->availableGeometry().height() - 48 : 900;
	return qBound( minimumHeight, totalHeight, maxHeight );
}

