/*
 * CimedVersionCompatibility.cpp - inbound version compatibility checks
 */

#include "CimedVersionCompatibility.h"

#include <QAbstractSocket>
#include <QHostInfo>
#include <QNetworkInterface>

#include "AccessLogAdLookup_win.h"
#include "CimedBuildSignature.h"
#include "CimedVersionAlertWriter.h"
#include "ComputerSupportInfo.h"
#include "Logger.h"
#include "VncServerClient.h"

namespace
{

QString normalizeIpAddress( const QString& ipAddress )
{
	static const auto ipv4MappedPrefix = QStringLiteral( "::ffff:" );
	if( ipAddress.startsWith( ipv4MappedPrefix, Qt::CaseInsensitive ) )
	{
		return ipAddress.mid( ipv4MappedPrefix.size() );
	}

	return ipAddress;
}

bool isLoopbackClientAddress( const QString& ip )
{
	return ip == QLatin1String( "127.0.0.1" ) ||
		   ip == QLatin1String( "::1" ) ||
		   ip == QLatin1String( "0:0:0:0:0:0:0:1" );
}

QString resolvedHostName( const QString& ipAddress )
{
	const auto normalizedIpAddress = normalizeIpAddress( ipAddress );
	const auto hostInfo = QHostInfo::fromName( normalizedIpAddress );
	if( hostInfo.error() == QHostInfo::NoError && hostInfo.hostName().isEmpty() == false )
	{
		return hostInfo.hostName();
	}

	return normalizedIpAddress;
}

bool isSentinelIpv4( const QString& ip )
{
	return ip == QStringLiteral( "186.217.65.86" ) ||
		   ip == QStringLiteral( "186.217.65.74" ) ||
		   ip == QStringLiteral( "186.217.65.94" ) ||
		   ip == QStringLiteral( "186.217.65.72" );
}

}

bool CimedVersionCompatibility::isSentinelAlertHost()
{
	// Qualquer NIC local nos 4 IPs sentinela — não só o "primeiro" IPv4
	// (Hyper-V/vEthernet pode vir antes e anular o monitor).
	for( const auto& address : QNetworkInterface::allAddresses() )
	{
		if( address.protocol() == QAbstractSocket::IPv4Protocol &&
			address.isLoopback() == false &&
			isSentinelIpv4( address.toString() ) )
		{
			return true;
		}
	}

	return false;
}

void CimedVersionCompatibility::handleInboundClientSignature( VncServerClient* client,
															const QString& clientBuildSignature )
{
	if( client == nullptr )
	{
		return;
	}

	const auto originIp = normalizeIpAddress( client->hostAddress() );
	if( isLoopbackClientAddress( originIp ) )
	{
		return;
	}

	if( CimedBuildSignature::isHomologated( clientBuildSignature ) )
	{
		return;
	}

	CimedVersionAlertWriter::IncompatibleConnectionDetails details;
	details.originIp = originIp;
	details.originHost = resolvedHostName( originIp );
	// Username that the Master puts in the Veyon handshake:
	// - KeyFile: interactive LoginName of the Master process session
	// - Logon: the authentication account (may differ from the person at the console)
	details.adUser = client->username();
	details.adDisplayName = accessLogLookupDomainUserDisplayName( details.adUser );
#ifdef Q_OS_WIN
	// Optional secondary clue for the narrative log / ops (not used to override adUser).
	auto consoleUser = accessLogLookupRemoteInteractiveUser( details.originHost );
	if( consoleUser.isEmpty() && details.originHost.contains( QLatin1Char( '.' ) ) )
	{
		consoleUser = accessLogLookupRemoteInteractiveUser(
			details.originHost.section( QLatin1Char( '.' ), 0, 0 ) );
	}
	if( consoleUser.isEmpty() )
	{
		consoleUser = accessLogLookupRemoteInteractiveUser( originIp );
	}
	if( consoleUser.isEmpty() == false &&
		consoleUser.compare( details.adUser, Qt::CaseInsensitive ) != 0 )
	{
		vWarning() << "[cimed-version-alert] protocol user" << details.adUser
				   << "differs from Console session" << consoleUser;
		if( details.adDisplayName.isEmpty() == false )
		{
			details.adDisplayName = details.adDisplayName +
				QStringLiteral( " | sessao Windows: " ) + consoleUser;
		}
		else
		{
			details.adDisplayName = QStringLiteral( "sessao Windows: " ) + consoleUser;
		}
	}
#endif
	details.detectedVersion = CimedBuildSignature::describeDetectedVersion( clientBuildSignature );
	details.destinationHost = ComputerSupportInfo::hostname();
