	connect( closeButton, &QPushButton::clicked, this, &QDialog::accept );
	layout->addWidget( closeButton, 0, Qt::AlignCenter );
}

void ComputerSupportInfoDialog::showDialog()
{
	static QPointer<ComputerSupportInfoDialog> openDialog;

	if( openDialog )
	{
		vWarning() << "[support-info][f9] raising existing dialog";
		openDialog->raise();
		openDialog->activateWindow();
		return;
	}

	vWarning() << "[support-info][f9] creating support info dialog";
	auto* dialog = new ComputerSupportInfoDialog();
	openDialog = dialog;
	dialog->setAttribute( Qt::WA_DeleteOnClose );
	QObject::connect( dialog, &QObject::destroyed, []() {
		openDialog = nullptr;
	} );

	dialog->show();
	dialog->raise();
	dialog->activateWindow();
	vWarning() << "[support-info][f9] dialog shown";
}

