{
	DesktopAccessConfirmDialog accessDialog( user, host, parent );
	VeyonCore::platform().coreFunctions().raiseWindow( &accessDialog, true );
	accessDialog.QDialog::exec();
	return accessDialog.m_choice;
}

DesktopAccessConfirmDialog::DesktopAccessConfirmDialog( const QString& user,
														const QString& host,
														QWidget* parent ) :
	QDialog( parent ),
	m_choice( DesktopAccessDialog::ChoiceNo )
{
	const auto windowTitle = tr( "Confirm desktop access" );
	setWindowIcon( CimedDialogStyle::standardWindowIcon() );

	QWidget* headerWidget = nullptr;
	QWidget* brandPanel = nullptr;
	QWidget* contentPanel = nullptr;
	QVBoxLayout* contentLayout = nullptr;
	QWidget* footerWidget = nullptr;

	CimedDialogStyle::buildDialogShell( this,
										windowTitle,
										CimedDialogStyle::StandardDialogWidth,
										CimedDialogStyle::TallDialogHeight,
										CimedDialogStyle::HeaderIcon::None,
										headerWidget,
										brandPanel,
										contentPanel,
										contentLayout,
										footerWidget );

	Q_UNUSED( headerWidget )
	Q_UNUSED( brandPanel )
	Q_UNUSED( footerWidget )
	Q_UNUSED( user )
	Q_UNUSED( host )

	auto* heroIcon = new QLabel( contentPanel );
	heroIcon->setAlignment( Qt::AlignHCenter );
	heroIcon->setPixmap( CimedDialogStyle::drawDesktopAccessHeroIcon( 72 ) );
	contentLayout->addWidget( heroIcon );
	contentLayout->addSpacing( 4 );

	auto* messageLabel = new QLabel(
		tr( "Um usuário deseja acessar sua área de trabalho. Deseja permitir?" ),
		contentPanel );
	messageLabel->setWordWrap( true );
	messageLabel->setAlignment( Qt::AlignHCenter );
	messageLabel->setStyleSheet( QStringLiteral(
		"font-size: 13px; font-weight: 600; color: #e2e8f0; line-height: 1.45;" ) );
	contentLayout->addWidget( messageLabel );
	contentLayout->addSpacing( 12 );

	auto* buttonsGrid = new QGridLayout();
	buttonsGrid->setHorizontalSpacing( 10 );
	buttonsGrid->setVerticalSpacing( 10 );

	auto* yesButton = CimedDialogStyle::createPrimaryButton(
		contentPanel,
		tr( "SIM" ),
		CimedDialogStyle::drawButtonIcon( QStringLiteral( "check" ) ) );
	auto* alwaysButton = CimedDialogStyle::createAccentButton(
		contentPanel,
		tr( "SEMPRE" ),
		CimedDialogStyle::drawButtonIcon( QStringLiteral( "star" ) ) );
	auto* noButton = CimedDialogStyle::createDenyButton(
		contentPanel,
		tr( "NAO" ),
		CimedDialogStyle::drawButtonIcon( QStringLiteral( "deny" ) ) );
	auto* neverButton = CimedDialogStyle::createSecondaryButton( contentPanel, tr( "NUNCA" ) );
	neverButton->setIcon( QIcon( CimedDialogStyle::drawButtonIcon( QStringLiteral( "deny" ) ) ) );
	neverButton->setIconSize( QSize( 16, 16 ) );

	for( auto* button : { yesButton, alwaysButton, noButton, neverButton } )
	{
		button->setMinimumHeight( 48 );
		button->setMinimumWidth( 108 );
	}

	buttonsGrid->addWidget( yesButton, 0, 0 );
	buttonsGrid->addWidget( alwaysButton, 0, 1 );
	buttonsGrid->addWidget( noButton, 1, 0 );
	buttonsGrid->addWidget( neverButton, 1, 1 );

	contentLayout->addLayout( buttonsGrid );
	contentLayout->addStretch();

	connect( yesButton, &QPushButton::clicked, this, [this]() {
		m_choice = DesktopAccessDialog::ChoiceYes;
		accept();
	} );
	connect( alwaysButton, &QPushButton::clicked, this, [this]() {
		m_choice = DesktopAccessDialog::ChoiceAlways;
		accept();
	} );
	connect( noButton, &QPushButton::clicked, this, [this]() {
		m_choice = DesktopAccessDialog::ChoiceNo;
		reject();
	} );
	connect( neverButton, &QPushButton::clicked, this, [this]() {
		m_choice = DesktopAccessDialog::ChoiceNever;
		accept();
	} );

	neverButton->setDefault( true );
	neverButton->setFocus();
}

void DesktopAccessConfirmDialog::reject()
{
	m_choice = DesktopAccessDialog::ChoiceNo;
	QDialog::reject();
}

