#include "SharedConnectionBus.h"

#include <QDateTime>
#include <QProcessEnvironment>

#include "Logger.h"

SharedConnectionBus& SharedConnectionBus::instance()
{
	static SharedConnectionBus bus;
	return bus;
}



bool SharedConnectionBus::isEnabled()
{
	const auto value = QProcessEnvironment::systemEnvironment()
						   .value( QStringLiteral( "VEYON_SHARED_CONNECTION_STATE" ) );
	return value == QLatin1String( "1" ) ||
		   value.compare( QLatin1String( "true" ), Qt::CaseInsensitive ) == 0;
}



SharedConnectionBus::SharedConnectionBus( QObject* parent ) :
	QObject( parent )
{
	qRegisterMetaType<SharedConnectionState>( "SharedConnectionState" );
}



void SharedConnectionBus::publishUpsert( const SharedConnectionState& state )
{
	if( isEnabled() == false || state.isValid() == false )
	{
		return;
	}

	if( state.status == SharedConnectionState::Status::Ended )
	{
		publishEnded( state.connectionId );
		return;
	}

	auto stored = state;
	if( stored.updatedAtMs <= 0 )
	{
		stored.updatedAtMs = QDateTime::currentMSecsSinceEpoch();
	}

	m_sessions.insert( stored.connectionId, stored );
	vDebug() << "[shared-connection] upsert"
			 << stored.connectionId
			 << stored.originIp
			 << "->"
			 << stored.destinationIp;
	Q_EMIT connectionUpserted( stored );
}



void SharedConnectionBus::publishEnded( const QString& connectionId )
{
	if( isEnabled() == false || connectionId.isEmpty() )
	{
		return;
	}

	if( m_sessions.remove( connectionId ) == 0 )
	{
		// Still notify subscribers so late joiners / races clear UI.
	}

	vDebug() << "[shared-connection] ended" << connectionId;
	Q_EMIT connectionEnded( connectionId );
}



QList<SharedConnectionState> SharedConnectionBus::snapshot() const
{
	if( isEnabled() == false )
	{
		return {};
	}

	return m_sessions.values();
}

