QString SharedConnectionHoverSubscriber::localIpv4()
{
	return SharedConnectionNetworkBroker::localIpv4();
}



bool SharedConnectionHoverSubscriber::isOwnOrigin( const SharedConnectionState& state ) const
{
	if( SharedConnectionNetworkBroker::isLocalInterfaceIp( state.originIp ) )
	{
		return true;
	}

	const auto localIp = localIpv4();
	if( localIp.isEmpty() == false && state.originIp == localIp )
	{
		return true;
	}

	const auto host = QHostInfo::localHostName();
	if( host.isEmpty() == false &&
		( state.originHost.compare( host, Qt::CaseInsensitive ) == 0 ||
		  state.originHost.startsWith( host + QLatin1Char( '.' ), Qt::CaseInsensitive ) ) )
	{
		return true;
	}

	return false;
}



void SharedConnectionHoverSubscriber::start()
{
	if( m_started )
	{
		return;
	}
	m_started = true;

	if( SharedConnectionBus::isEnabled() == false )
	{
		vDebug() << "[shared-connection][subscriber] disabled (VEYON_SHARED_CONNECTION_STATE not set)";
		return;
	}

	auto& bus = SharedConnectionBus::instance();
	connect( &bus, &SharedConnectionBus::connectionUpserted,
			 this, &SharedConnectionHoverSubscriber::onConnectionUpserted );
	connect( &bus, &SharedConnectionBus::connectionEnded,
			 this, &SharedConnectionHoverSubscriber::onConnectionEnded );

	const auto existing = bus.snapshot();
	for( const auto& state : existing )
	{
		onConnectionUpserted( state );
	}

	vWarning() << "[shared-connection][subscriber] started"
			   << "localIp" << localIpv4()
			   << "snapshot" << existing.size();

	// Phase 4: LAN broker (no-op if network disabled / bind fails).
	auto* broker = new SharedConnectionNetworkBroker( this );
	broker->start();

	maybeScheduleSelfTestMirror();
}



void SharedConnectionHoverSubscriber::onConnectionUpserted( const SharedConnectionState& state )
{
	if( SharedConnectionBus::isEnabled() == false || state.isValid() == false )
	{
		return;
	}

	if( state.status == SharedConnectionState::Status::Ended )
	{
		onConnectionEnded( state.connectionId );
		return;
	}

	// Never mirror our own outbound sessions — local hover stack already owns them.
	if( isOwnOrigin( state ) )
	{
		vDebug() << "[shared-connection][subscriber] skip own origin"
				 << state.connectionId << state.originIp;
		return;
	}

	const auto traySessionId = SharedConnectionState::mirroredTraySessionId( state.connectionId );
	const auto user = state.clientUser.isEmpty() ? QStringLiteral( "remoto" ) : state.clientUser;

	if( m_mirroredConnectionIds.contains( state.connectionId ) )
	{
		return;
	}

	SystemTrayIcon::notifyOutboundTraySession( SystemTrayIcon::OutboundHoverOperation::Add,
											   traySessionId,
											   SystemTrayIcon::StatusIndicator::Connected,
											   user,
											   state.originHost,
											   state.originIp,
											   state.destinationHost,
											   state.destinationIp );

	m_mirroredConnectionIds.insert( state.connectionId );

	vWarning() << "[shared-connection][subscriber] mirror Add"
			   << state.connectionId
			   << state.originIp << "->" << state.destinationIp;
}



void SharedConnectionHoverSubscriber::onConnectionEnded( const QString& connectionId )
{
	if( connectionId.isEmpty() )
	{
		return;
	}

	if( m_mirroredConnectionIds.remove( connectionId ) == false )
	{
		return;
	}

	SystemTrayIcon::notifyOutboundTraySessionRemove(
		SharedConnectionState::mirroredTraySessionId( connectionId ) );

	vWarning() << "[shared-connection][subscriber] mirror Remove" << connectionId;
}



void SharedConnectionHoverSubscriber::maybeScheduleSelfTestMirror()
{
	const auto value = QProcessEnvironment::systemEnvironment()
						   .value( QStringLiteral( "VEYON_SHARED_CONNECTION_TEST_MIRROR" ) );
	const bool enabled = value == QLatin1String( "1" ) ||
						 value.compare( QLatin1String( "true" ), Qt::CaseInsensitive ) == 0;
	if( enabled == false )
	{
		return;
	}

	// Synthetic foreign session so this Master can validate mirrored hover UI
	// without a second machine / broker (phase 3 only).
	QTimer::singleShot( 2500, this, []() {
		SharedConnectionState state;
		state.connectionId = QStringLiteral( "test-mirror-phase3" );
		state.originHost = QStringLiteral( "CIMED-TEST-ORIGIN" );
		state.originIp = QStringLiteral( "186.217.65.90" );
		state.destinationHost = QStringLiteral( "CIMED-TEST-DEST" );
		state.destinationIp = QStringLiteral( "186.217.65.55" );
		state.clientUser = QStringLiteral( "teste-mirror" );
		state.status = SharedConnectionState::Status::Monitoring;
		state.updatedAtMs = QDateTime::currentMSecsSinceEpoch();
		SharedConnectionBus::instance().publishUpsert( state );
		vWarning() << "[shared-connection][subscriber] TEST mirror upsert injected";
	} );

	QTimer::singleShot( 12000, this, []() {
		SharedConnectionBus::instance().publishEnded( QStringLiteral( "test-mirror-phase3" ) );
		vWarning() << "[shared-connection][subscriber] TEST mirror ended";
	} );
}

