qint64 SharedConnectionNetworkBroker::envInt( const QString& name, qint64 fallback )
{
	const auto value = QProcessEnvironment::systemEnvironment().value( name );
	if( value.isEmpty() )
	{
		return fallback;
	}

	bool ok = false;
	const auto parsed = value.toLongLong( &ok );
	return ok ? parsed : fallback;
}



bool SharedConnectionNetworkBroker::isNetworkEnabled()
{
	if( SharedConnectionBus::isEnabled() == false )
	{
		return false;
	}

	const auto value = QProcessEnvironment::systemEnvironment()
						   .value( QStringLiteral( "VEYON_SHARED_CONNECTION_NETWORK" ) );
	if( value.isEmpty() )
	{
