quint16 SharedConnectionNetworkBroker::udpPort()
{
	const auto port = envInt( QStringLiteral( "VEYON_SHARED_CONNECTION_PORT" ), DefaultPort );
	if( port <= 0 || port > 65535 )
	{
		return DefaultPort;
	}
	return static_cast<quint16>( port );
}



qint64 SharedConnectionNetworkBroker::ttlMs()
{
	const auto ttl = envInt( QStringLiteral( "VEYON_SHARED_CONNECTION_TTL_MS" ), DefaultTtlMs );
	return ttl > 5000 ? ttl : DefaultTtlMs;
}



QString SharedConnectionNetworkBroker::localIpv4()
{
	const auto peersEnv = QProcessEnvironment::systemEnvironment()
							  .value( QStringLiteral( "VEYON_SHARED_CONNECTION_PEERS" ) );
	QStringList peerIps;
	for( const auto& peer : peersEnv.split( QLatin1Char( ',' ), Qt::SkipEmptyParts ) )
	{
		peerIps.append( peer.trimmed() );
	}

	struct Candidate
	{
		QString ip;
		bool virtualIface = false;
	};
	QList<Candidate> candidates;

	for( const auto& iface : QNetworkInterface::allInterfaces() )
	{
		if( ( iface.flags() & QNetworkInterface::IsUp ) == 0 ||
			( iface.flags() & QNetworkInterface::IsLoopBack ) != 0 )
		{
			continue;
		}

		const auto label = ( iface.humanReadableName() + QLatin1Char( ' ' ) + iface.name() ).toLower();
		const bool virtualIface =
			label.contains( QLatin1String( "hyper-v" ) ) ||
			label.contains( QLatin1String( "vethernet" ) ) ||
			label.contains( QLatin1String( "vmware" ) ) ||
			label.contains( QLatin1String( "virtualbox" ) ) ||
			label.contains( QLatin1String( "vbox" ) ) ||
			label.contains( QLatin1String( "docker" ) ) ||
			label.contains( QLatin1String( "wsl" ) ) ||
			label.contains( QLatin1String( "vpn" ) ) ||
			label.contains( QLatin1String( "tap-windows" ) );

		for( const auto& entry : iface.addressEntries() )
		{
			const auto ip = entry.ip();
			if( ip.protocol() != QAbstractSocket::IPv4Protocol ||
				ip.isLoopback() ||
				ip.isLinkLocal() )
			{
				continue;
			}

			const auto ipStr = ip.toString();
			if( peerIps.contains( ipStr ) )
			{
				return ipStr;
			}

			candidates.append( { ipStr, virtualIface } );
		}
	}

	for( const auto& candidate : candidates )
	{
		if( candidate.virtualIface == false )
		{
			return candidate.ip;
		}
	}

	if( candidates.isEmpty() == false )
	{
		return candidates.first().ip;
	}

	return {};
}



bool SharedConnectionNetworkBroker::isLocalInterfaceIp( const QString& ip )
{
	if( ip.isEmpty() )
	{
		return false;
	}

	for( const auto& address : QNetworkInterface::allAddresses() )
	{
		if( address.protocol() == QAbstractSocket::IPv4Protocol &&
			address.isLoopback() == false &&
			address.toString() == ip )
		{
			return true;
		}
	}

	return false;
}



