void SharedConnectionNetworkBroker::start()
{
	if( m_started )
	{
		return;
	}
	m_started = true;

	if( isNetworkEnabled() == false )
	{
		vDebug() << "[shared-connection][broker] disabled";
		return;
	}

	m_localIp = localIpv4();
	const auto port = udpPort();

	connect( &m_socket, &QUdpSocket::readyRead, this, &SharedConnectionNetworkBroker::onReadyRead );

	if( m_socket.bind( QHostAddress::AnyIPv4, port,
					   QUdpSocket::ShareAddress | QUdpSocket::ReuseAddressHint ) == false )
	{
		vWarning() << "[shared-connection][broker] bind failed"
					<< port << m_socket.errorString();
		return;
	}

	// Multicast so Master + Server on the same host both receive (Windows UDP
	// unicast/broadcast to a reused port often delivers to only one socket).
	const auto group = multicastGroup();
	if( m_socket.joinMulticastGroup( group ) == false )
	{
		vWarning() << "[shared-connection][broker] multicast join failed"
					<< group.toString() << m_socket.errorString();
	}

	auto& bus = SharedConnectionBus::instance();
	connect( &bus, &SharedConnectionBus::connectionUpserted,
			 this, &SharedConnectionNetworkBroker::onLocalUpserted );
	connect( &bus, &SharedConnectionBus::connectionEnded,
			 this, &SharedConnectionNetworkBroker::onLocalEnded );

	m_timer = new QTimer( this );
	connect( m_timer, &QTimer::timeout, this, &SharedConnectionNetworkBroker::onTick );
	m_timer->start( TickIntervalMs );

	vWarning() << "[shared-connection][broker] started"
			   << "port" << port
			   << "localIp" << m_localIp
			   << "multicast" << group.toString()
			   << "ttlMs" << ttlMs();

	// Late join: ask peers for active sessions.
	QTimer::singleShot( 800, this, &SharedConnectionNetworkBroker::requestSnapshot );
}



