QJsonObject SharedConnectionState::toJson() const
{
	QJsonObject object;
	object.insert( QStringLiteral( "connectionId" ), connectionId );
	object.insert( QStringLiteral( "originHost" ), originHost );
	object.insert( QStringLiteral( "originIp" ), originIp );
	object.insert( QStringLiteral( "destinationHost" ), destinationHost );
	object.insert( QStringLiteral( "destinationIp" ), destinationIp );
	object.insert( QStringLiteral( "clientUser" ), clientUser );
	object.insert( QStringLiteral( "status" ),
				   status == Status::Ended ? QStringLiteral( "ENDED" )
										   : QStringLiteral( "MONITORING" ) );
	object.insert( QStringLiteral( "updatedAtMs" ), updatedAtMs );
	return object;
}



SharedConnectionState SharedConnectionState::fromJson( const QJsonObject& object )
{
	SharedConnectionState state;
	state.connectionId = object.value( QStringLiteral( "connectionId" ) ).toString();
	state.originHost = object.value( QStringLiteral( "originHost" ) ).toString();
	state.originIp = object.value( QStringLiteral( "originIp" ) ).toString();
	state.destinationHost = object.value( QStringLiteral( "destinationHost" ) ).toString();
	state.destinationIp = object.value( QStringLiteral( "destinationIp" ) ).toString();
	state.clientUser = object.value( QStringLiteral( "clientUser" ) ).toString();
	state.updatedAtMs = static_cast<qint64>( object.value( QStringLiteral( "updatedAtMs" ) ).toDouble() );

	const auto statusText = object.value( QStringLiteral( "status" ) ).toString();
	state.status = ( statusText.compare( QStringLiteral( "ENDED" ), Qt::CaseInsensitive ) == 0 )
					   ? Status::Ended
					   : Status::Monitoring;
	return state;
}

