	QString originHost;
	QString originIp;
	QString destinationHost;
	QString destinationIp;
	QString clientUser;
	Status status = Status::Monitoring;
	qint64 updatedAtMs = 0;

	bool isValid() const
	{
		return connectionId.isEmpty() == false &&
			   originIp.isEmpty() == false &&
			   destinationIp.isEmpty() == false;
	}

	/** Tray session id for mirrored (non-owner) hovers — never equals a local UUID. */
	static QString mirroredTraySessionId( const QString& connectionId )
	{
		return QStringLiteral( "mirror:%1" ).arg( connectionId );
	}

	static bool isMirroredTraySessionId( const QString& traySessionId )
	{
		return traySessionId.startsWith( QStringLiteral( "mirror:" ) );
	}

	QJsonObject toJson() const;
	static SharedConnectionState fromJson( const QJsonObject& object );
};

