void TamperLogProtector::writeTamperResponse( const QString& response )

{

	const auto responsePath = QDir( QCoreApplication::applicationDirPath() ).filePath(

		QStringLiteral( "acessos_tamper_response.txt" ) );



	QFile file( responsePath );

	if( file.open( QIODevice::WriteOnly | QIODevice::Text | QIODevice::Truncate ) )

	{

		file.write( response.toUtf8() );

	}

}



TamperLogProtector::TamperLogProtector( FeatureWorkerManager& featureWorkerManager, QObject* parent ) :

	QObject( parent ),

	m_featureWorkerManager( featureWorkerManager )

{

	refreshBackups();

	auto* pollTimer = new QTimer( this );

	connect( pollTimer, &QTimer::timeout, this, [this]() {

		checkNetworkAccessFile();

		checkNetworkFile();

	} );

	pollTimer->start( 1000 );

	VeyonCore::builtinFeatures().systemTrayIcon().ensureSessionWorker( m_featureWorkerManager );

}



bool TamperLogProtector::isAccessLogPath( const QString& filePath ) const

{

	return filePath == AccessLogWriter::networkAccessLogPath();

}



void TamperLogProtector::setWatcherSuppressed( bool suppressed )

{

	if( suppressed )

	{

		++m_suppressWatcherDepth;

	}

	else if( m_suppressWatcherDepth > 0 )

	{

		--m_suppressWatcherDepth;

	}

}



void TamperLogProtector::beginProtectedBatch()

{

	setWatcherSuppressed( true );

}



void TamperLogProtector::endProtectedBatch()

{

	refreshBackups();

	setWatcherSuppressed( false );

}



void TamperLogProtector::refreshBackups()

{

	QString content;



	if( AccessLogWriter::tryReadLogFileContent( AccessLogWriter::networkAccessLogPath(), content ) )

	{

		m_networkAccessBackup = content;

	}

	if( AccessLogWriter::tryReadLogFileContent( AccessLogWriter::networkTamperedLogPath(), content ) )

	{

		m_networkBackup = content;

	}

}



void TamperLogProtector::prepareWrite( const QString& filePath )

{

	Q_UNUSED( filePath )

	setWatcherSuppressed( true );

}



void TamperLogProtector::finalizeWrite( const QString& filePath )

{

	updateBackupForPath( filePath );

	setWatcherSuppressed( false );

}



void TamperLogProtector::updateBackupForPath( const QString& filePath )

{

	QString content;



	if( filePath == AccessLogWriter::networkAccessLogPath() )

	{

		if( AccessLogWriter::tryReadLogFileContent( filePath, content ) )

		{

			m_networkAccessBackup = content;

		}

	}

	else if( filePath == AccessLogWriter::networkTamperedLogPath() )

	{

		if( AccessLogWriter::tryReadLogFileContent( filePath, content ) )

		{

			m_networkBackup = content;

		}

	}

}



bool TamperLogProtector::verifyAdminPassword( const QString& password )

{

	return passwordSha256Hex( password ) == QLatin1String( AdminPasswordHash );

}



void TamperLogProtector::reportUnauthorizedChange( const QString& filePath, const QString& fileLabel )

{

	vWarning() << "[tamper-log-protection] unauthorized change detected on" << fileLabel;



	if( isAccessLogPath( filePath ) && QFile::exists( filePath ) )

	{

		AccessLogWriter::recordTamperAlertForAccessLogTamper( filePath, QStringLiteral( "rede" ) );

	}



	updateBackupForPath( filePath );

}



void TamperLogProtector::checkProtectedFile( const QString& filePath, const QString& backup, const QString& fileLabel )
{
	if( isWatcherSuppressed() )
	{
		return;
	}

	if( QFile::exists( filePath ) == false )
	{
		if( backup.isEmpty() == false )
		{
			reportUnauthorizedChange( filePath, fileLabel );
		}
		return;
	}

	QString currentContent;
	if( AccessLogWriter::tryReadLogFileContent( filePath, currentContent ) == false )
	{
		vWarning() << "[tamper-log-protection] skipping check due to read failure on" << fileLabel;
		return;
	}

	if( AccessLogWriter::logContentsEqual( currentContent, backup ) )
	{
		return;
	}

	if( AccessLogWriter::isLegitimateProtectedLogAppend( backup, currentContent ) )
	{
		updateBackupForPath( filePath );
		return;
	}

	// Mid-write / share lag: retry before treating as adulteration.
	QString stableContent = currentContent;
	for( int attempt = 0; attempt < 3; ++attempt )
	{
		QThread::msleep( 400 );

		QString retryContent;
		if( AccessLogWriter::tryReadLogFileContent( filePath, retryContent ) == false )
		{
			continue;
		}

		stableContent = retryContent;

		if( AccessLogWriter::isLegitimateProtectedLogAppend( backup, retryContent ) )
		{
			updateBackupForPath( filePath );
			return;
		}

		if( isAccessLogPath( filePath ) )
		{
			if( AccessLogWriter::accessLogFileHasValidIntegrity( filePath ) )
			{
				vDebug() << "[tamper-log-protection] ignoring change on access log with valid hashes";
				updateBackupForPath( filePath );
				return;
			}

			// Same invalid signatures as backup => old junk; do not re-alert on legitimate access.
			if( AccessLogWriter::accessLogHasNewIntegrityIssues( backup, retryContent ) == false )
			{
				vDebug() << "[tamper-log-protection] ignoring access log change without new integrity issues";
				updateBackupForPath( filePath );
				return;
			}
		}
	}

	if( isAccessLogPath( filePath ) )
	{
		if( AccessLogWriter::accessLogFileHasValidIntegrity( filePath ) ||
			AccessLogWriter::accessLogHasNewIntegrityIssues( backup, stableContent ) == false )
		{
			updateBackupForPath( filePath );
			return;
		}
	}

	reportUnauthorizedChange( filePath, fileLabel );
}

void TamperLogProtector::checkNetworkAccessFile()
{
	checkProtectedFile( AccessLogWriter::networkAccessLogPath(), m_networkAccessBackup,
						QStringLiteral( "rede acessos_veyon" ) );
}

void TamperLogProtector::checkNetworkFile()
{
	checkProtectedFile( AccessLogWriter::networkTamperedLogPath(), m_networkBackup,
						QStringLiteral( "rede acessos_veyon_ad" ) );
}

