						  handleShortcut( shortcut );
					  } );

	m_computerControlInterface->setUpdateMode( ComputerControlInterface::UpdateMode::Live );
}



VncView::~VncView()
{
	unpressAllModifiers();

	m_computerControlInterface->setUpdateMode( m_previousUpdateMode );

	delete m_keyboardShortcutTrapper;
}



