Object& Object::operator=( const Object& ref )
{
	if( &ref == this )
	{
		return *this;
	}

	if( m_customStore == false &&
			ref.m_customStore == false &&
			ref.m_store )
	{
		const auto backend = ref.m_store->backend();
		const auto scope = ref.m_store->scope();

		delete m_store;

		m_store = createStore( backend, scope );
