QString monitoringIpFromHost( const QString& host )
{
	const auto address = QHostAddress( host );
	if( address.isNull() == false && address.protocol() == QAbstractSocket::IPv4Protocol )
	{
		return address.toString();
	}

	const auto hostInfo = QHostInfo::fromName( host );
	for( const auto& addr : hostInfo.addresses() )
	{
		if( addr.protocol() == QAbstractSocket::IPv4Protocol && addr.isLoopback() == false )
		{
			return addr.toString();
		}
	}

	return host;
}

QString monitoringHostNameFromAddress( const QString& address )
{
	if( address.isEmpty() )
	{
		return {};
	}

	const auto hostInfo = QHostInfo::fromName( address );
	if( hostInfo.error() == QHostInfo::NoError && hostInfo.hostName().isEmpty() == false )
	{
		return hostInfo.hostName();
	}

	return address;
}

