	{
		m_originalParent = parentWidget();
		setParent(nullptr);
		setWindowTitle(tr("Veyon Master – Slideshow"));
		showMaximized();
	}
	else
	{
		setParent(m_originalParent);
		m_originalParent = nullptr;
	}
}

