{
	// prevent double deletion of toplevel widget
	if( m_toplevel == obj )
	{
		m_toplevel = nullptr;
	}

	deleteLater();
}



void DemoClient::resizeToplevelWidget()
{
	if( m_toplevel->windowState() & Qt::WindowFullScreen )
	{
		m_vncView->setFixedSize(m_toplevel->size());
	}
	else
	{
		m_toplevel->resize(m_vncView->sizeHint());
	}
}

