{
	return m_failedFileIndices.isEmpty() == false;
}



bool FileTransferController::isFileFailed( int fileIndex ) const
{
	return m_failedFileIndices.contains( fileIndex );
}



void FileTransferController::handleRemoteResult( const QUuid& transferId, bool success,
												 const QString& errorMessage, const QString& destinationPath )
{
	if( transferId.isNull() || transferId != m_currentTransferId ||
		m_fileState != FileStateWaitingForRemoteAck )
	{
		return;
	}

	m_remoteAckReceived = true;
	m_remoteAckSuccess = success;
	m_remoteAckErrorMessage = errorMessage;
	m_remoteDestinationPath = destinationPath;
}



void FileTransferController::process()
{
	switch( m_fileState )
	{
	case FileStateOpen:
		if( openFile() )
		{
			m_fileState = FileStateTransferring;
		}
		else
		{
			m_fileState = FileStateFinished;
		}
		break;

	case FileStateTransferring:
		if( transferFile() )
		{
			finishFile();
			m_fileState = FileStateWaitingForRemoteAck;
			m_remoteAckReceived = false;
			m_remoteAckSuccess = false;
			m_remoteAckErrorMessage.clear();
			m_remoteDestinationPath.clear();
			m_remoteAckTimer.start();
		}
		break;

	case FileStateWaitingForRemoteAck:
		if( m_remoteAckReceived )
		{
			if( m_remoteAckSuccess == false )
			{
				m_failedFileIndices.insert( m_currentFileIndex );
				Q_EMIT errorOccured( m_remoteAckErrorMessage.isEmpty() ?
										 tr( "The remote computer failed to receive file %1." ).
										 arg( m_files.value( m_currentFileIndex ) )
									   :
										 m_remoteAckErrorMessage );
			}
			m_fileState = FileStateFinished;
		}
		else if( m_remoteAckTimer.hasExpired( RemoteAckTimeout ) )
		{
			m_failedFileIndices.insert( m_currentFileIndex );
			Q_EMIT errorOccured( tr( "Timed out waiting for the remote computer to confirm receipt of file %1." ).
								 arg( m_files.value( m_currentFileIndex ) ) );
			m_fileState = FileStateFinished;
		}
		break;

	case FileStateFinished:
		if( m_fileReadThread )
		{
			delete m_fileReadThread;
			m_fileReadThread = nullptr;
		}

		m_currentTransferId = QUuid();

		if( ++m_currentFileIndex >= m_files.count() )
		{
			if( m_flags.testFlag( OpenTransferFolder ) )
			{
				m_plugin->sendOpenTransferFolderMessage( m_interfaces );
			}

			m_plugin->sendStopWorkerMessage(m_interfaces);

			m_processTimer.stop();
			Q_EMIT finished();
		}
		else
		{
			m_fileState = FileStateOpen;
		}
		break;
	}

	updateProgress();
}



bool FileTransferController::openFile()
{
	if( m_currentFileIndex >= m_files.count() )
	{
		return false;
	}

	m_fileReadThread = new FileReadThread(m_files.value(m_currentFileIndex), this);

	if( m_fileReadThread->start() == false )
	{
		delete m_fileReadThread;
		m_fileReadThread = nullptr;
		Q_EMIT errorOccured( tr( "Could not open file %1 for reading! Please check your permissions!" ).arg( m_currentFileIndex ) );
		return false;
	}

	// start reading initial chunk in background
	m_fileReadThread->readNextChunk( ChunkSize );

	m_currentTransferId = QUuid::createUuid();

	m_plugin->sendStartMessage( m_currentTransferId, QFileInfo(m_files.value(m_currentFileIndex)).fileName(),
								m_flags.testFlag( OverwriteExistingFiles ), m_interfaces );

	return true;
}



bool FileTransferController::transferFile()
{
	if( m_fileReadThread == nullptr )
	{
		// something went wrong so finish this file
		return true;
	}

	// wait for all clients to catch up and current data chunk to be read completely
	if( allQueuesEmpty() == false || m_fileReadThread->isChunkReady() == false )
	{
		return false;
	}

	m_plugin->sendDataMessage( m_currentTransferId, m_fileReadThread->currentChunk(), m_interfaces );

	m_fileReadThread->readNextChunk( ChunkSize );

	return m_fileReadThread->atEnd();
}



