// Conexao consigo mesmo: feixe de luz em wireframe neon (Master -> Clients) — sem VNC real.
class LocalComputerFeedbackWidget : public QWidget
{
public:
	explicit LocalComputerFeedbackWidget( const QString& hostLabel, QWidget* parent = nullptr ) :
		QWidget( parent ),
		m_hostLabel( hostLabel ),
		m_depth( 0. )
	{
		setWindowTitle( tr( "Remote access - %1" ).arg( hostLabel ) );
		setAttribute( Qt::WA_DeleteOnClose, true );
		resize( 960, 600 );
		setMinimumSize( 640, 400 );

		auto* timer = new QTimer( this );
		connect( timer, &QTimer::timeout, this, [this]() {
			m_depth += 0.028;
			if( m_depth >= 1. )
			{
				m_depth -= 1.;
			}
			update();
		} );
		timer->start( 33 );

		show();
		raise();
		activateWindow();
	}

protected:
	void paintEvent( QPaintEvent* event ) override
	{
		Q_UNUSED(event)

		QPainter p( this );
		p.setRenderHint( QPainter::Antialiasing, true );

		const auto view = rect();
		drawBackground( p, view );
		drawHexGridFloor( p, view );

		const QPointF master( view.width() * 0.5, view.height() * 0.18 );
		const QList<QPointF> clients = {
			QPointF( view.width() * 0.18, view.height() * 0.72 ),
			QPointF( view.width() * 0.36, view.height() * 0.78 ),
			QPointF( view.width() * 0.64, view.height() * 0.78 ),
			QPointF( view.width() * 0.82, view.height() * 0.72 )
		};

		for( int i = 0; i < clients.size(); ++i )
		{
			drawWireframeBeam( p, master, clients.at( i ), i == 1 );
		}

		drawMasterNode( p, master );
		for( int i = 0; i < clients.size(); ++i )
		{
			drawClientPad( p, clients.at( i ), i + 1 );
		}

		drawVignette( p, view );
		drawCenterMessage( p, view );
	}

private:
	void drawBackground( QPainter& p, const QRect& view ) const
	{
		QLinearGradient background( view.topLeft(), view.bottomRight() );
		background.setColorAt( 0.0, QColor( 4, 8, 16 ) );
		background.setColorAt( 0.45, QColor( 2, 6, 14 ) );
		background.setColorAt( 1.0, QColor( 0, 2, 8 ) );
		p.fillRect( view, background );

		QRadialGradient glow( QPointF( view.width() * 0.5, view.height() * 0.22 ),
							  qMax( view.width(), view.height() ) * 0.42 );
		glow.setColorAt( 0.0, QColor( 0, 180, 255, 55 ) );
		glow.setColorAt( 0.45, QColor( 0, 120, 220, 18 ) );
		glow.setColorAt( 1.0, QColor( 0, 0, 0, 0 ) );
		p.fillRect( view, glow );
	}

	void drawHexGridFloor( QPainter& p, const QRect& view ) const
	{
		const auto horizonY = view.height() * 0.42;
		const auto vanish = QPointF( view.width() * 0.5, horizonY );
		p.setPen( QPen( QColor( 0, 200, 255, 28 ), 1.0 ) );

		for( int row = 0; row < 14; ++row )
		{
			const auto t = row / 13.0;
			const auto y = horizonY + t * t * ( view.height() - horizonY );
			const auto halfSpan = view.width() * ( 0.12 + t * 0.55 );
			p.drawLine( QPointF( vanish.x() - halfSpan, y ), QPointF( vanish.x() + halfSpan, y ) );
		}

		for( int col = -8; col <= 8; ++col )
		{
			const auto edgeX = vanish.x() + col * view.width() * 0.07;
			p.drawLine( vanish, QPointF( edgeX, view.height() + 8 ) );
		}
	}

	static QPointF bezierPoint( const QPointF& a, const QPointF& b, const QPointF& c, double t )
	{
		const auto u = 1.0 - t;
		return a * ( u * u ) + b * ( 2.0 * u * t ) + c * ( t * t );
	}

