	{
		const QPointF control( ( from.x() + to.x() ) * 0.5,
							   qMin( from.y(), to.y() ) + qAbs( to.y() - from.y() ) * 0.35 );
		const auto normal = QPointF( -( to.y() - from.y() ), to.x() - from.x() );
		const auto normalLen = qSqrt( normal.x() * normal.x() + normal.y() * normal.y() );
		const auto nx = normalLen > 0.001 ? normal.x() / normalLen : 0.0;
		const auto ny = normalLen > 0.001 ? normal.y() / normalLen : 1.0;

		const int strandCount = emphasize ? 7 : 5;
		const auto strandSpacing = emphasize ? 3.2 : 2.4;

		for( int strand = 0; strand < strandCount; ++strand )
		{
			const auto offset = ( strand - ( strandCount - 1 ) * 0.5 ) * strandSpacing;
			QPainterPath path;
			bool started = false;
			for( int step = 0; step <= 36; ++step )
			{
				const auto t = step / 36.0;
				const auto point = bezierPoint( from, control, to, t );
				const auto twist = qSin( t * 6.0 + m_depth * 6.28318530718 + strand * 0.7 ) * 1.1;
				const QPointF sample( point.x() + ( offset + twist ) * nx,
									  point.y() + ( offset + twist ) * ny );
				if( started == false )
				{
					path.moveTo( sample );
					started = true;
				}
				else
