				}
			}

			const auto alpha = emphasize ? 150 - strand * 12 : 95 - strand * 10;
			p.setPen( QPen( QColor( 0, 220, 255, qMax( 35, alpha ) ), emphasize ? 1.35 : 1.05 ) );
			p.drawPath( path );
		}

		// Pulsos de dados ao longo do feixe
		for( int pulse = 0; pulse < 3; ++pulse )
		{
