# Garante DistributeFiles sempre fora de Features\DisabledFeatures.
# Cirurgico: remove so o UID {4a70bd5a-...}. Nao altera outras features,
# nao mexe em logs/access control/shared-connection.
# Se corrigir o registro, reinicia VeyonService para:
#  1) FeatureManager reler DisabledFeatures
#  2) limpar worker zombie (worker que morreu no qFatal antes de conectar)
param(
    [switch]$Quiet,
    [switch]$NoServiceRestart
)

$ErrorActionPreference = "Stop"
$DistUid = "{4a70bd5a-fab2-4a4b-a92a-a1e81d2b75ed}"
$KeyPath = "SOFTWARE\Veyon Solutions\Veyon\Features"

function Write-Msg([string]$Message, [string]$Color = "Gray") {
    if (-not $Quiet) {
        Write-Host $Message -ForegroundColor $Color
    }
}

$base = [Microsoft.Win32.RegistryKey]::OpenBaseKey(
    [Microsoft.Win32.RegistryHive]::LocalMachine,
    [Microsoft.Win32.RegistryView]::Registry64)
$key = $base.OpenSubKey($KeyPath, $true)
if (-not $key) {
    Write-Msg "Features key ausente - nada a fazer." "Yellow"
    $base.Close()
    exit 0
}

$current = @($key.GetValue("DisabledFeatures"))
if ($current -notcontains $DistUid) {
    Write-Msg "OK: DistributeFiles ja habilitado (UID ausente)." "Green"
    $key.Close(); $base.Close()
    exit 0
}

$filtered = [string[]](@($current | Where-Object { $_ -and $_ -ne $DistUid }))
$key.SetValue("DisabledFeatures", $filtered, [Microsoft.Win32.RegistryValueKind]::MultiString)
$key.Close(); $base.Close()
$msg = "CORRIGIDO: removido DistributeFiles UID. DisabledFeatures count {0} -> {1}" -f $current.Count, $filtered.Count
Write-Msg $msg "Green"

if (-not $NoServiceRestart) {
    Write-Msg "Reiniciando VeyonService para limpar worker zombie / recarregar config..." "Cyan"
    try {
        Restart-Service -Name "VeyonService" -Force -ErrorAction Stop
        Write-Msg "VeyonService reiniciado." "Green"
    } catch {
        Write-Msg ("Aviso: falha ao reiniciar VeyonService: {0}" -f $_.Exception.Message) "Yellow"
        exit 2
    }
}
exit 0

# Instala o garantidor permanente de DistributeFiles (script + tarefa agendada).
# Cirurgico: nao reinicia VeyonService; nao altera outras features.
param(
    [Parameter(Mandatory = $true)]
    [string]$InstallDir,
    [switch]$Quiet
)

$ErrorActionPreference = "Stop"
$TaskName = "Veyon CIMED Ensure DistributeFiles"
$ScriptName = "ensure_distributefiles_enabled.ps1"

function Write-Msg([string]$Message, [string]$Color = "Gray") {
    if (-not $Quiet) {
        Write-Host $Message -ForegroundColor $Color
    }
}

$InstallDir = $InstallDir.TrimEnd('\', '/')
if (-not (Test-Path -LiteralPath $InstallDir)) {
    throw "InstallDir inexistente: $InstallDir"
}

$destScript = Join-Path $InstallDir $ScriptName
$srcCandidates = [System.Collections.Generic.List[string]]::new()
foreach ($cand in @((Join-Path $PSScriptRoot $ScriptName), $destScript)) {
    if ($cand -and (Test-Path -LiteralPath $cand)) {
        [void]$srcCandidates.Add($cand)
    }
}

if ($srcCandidates.Count -lt 1) {
    throw "Nao encontrei $ScriptName (esperado em scripts\ ou em InstallDir)."
}

$src = $srcCandidates[0]
Copy-Item -LiteralPath $src -Destination $destScript -Force
Write-Msg "Script: $destScript" "Cyan"

# Uma vez agora
$ensureArgs = @("-NoProfile", "-ExecutionPolicy", "Bypass", "-File", $destScript)
if ($Quiet) { $ensureArgs += "-Quiet" }
& powershell.exe @ensureArgs
if ($LASTEXITCODE -ne 0) {
    throw "ensure_distributefiles_enabled falhou (exit $LASTEXITCODE)"
}

